cases.bad:
.cell-chip { background: surface-hover; color: text-secondary; border: 1px solid border; }
.cell-chip:hover { background: primary-subtle; color: primary; border-color: primary; }
.cell-chip--active { background: primary; color: text-inverse; border-color: primary; }
.cell-chip--active:hover { background: primary-hover; }

// JS:
chip.className = 'btn cell-chip' + (active ? ' cell-chip--active' : '');

cases.good:
// components.css
.btn--outline { background: transparent; color: text; border: 1px solid border; }
.btn--outline:hover { background: surface-hover; border-color: border-focus; }
.btn--primary { background: primary; color: text-inverse; }
.btn--primary:hover { background: primary-hover; }

// CSS:
.cell-chip { border-radius: var(--radius-full); max-width: 22ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

// JS:
chip.className = 'btn ' + (active ? 'btn--primary ' : 'btn--outline ') + 'cell-chip';
